package calc

/** Signals that an expression could not be evaluated (syntax error, division by zero or overflow). */
class EvaluationException(message: String) : Exception(message, null, false, false)

/**
 * Recursive-descent evaluator for 64-bit signed integer expressions.
 *
 * ```
 * expr    := term    (('+' | '-') term)*
 * term    := unary   (('*' | '/' | '%') unary)*
 * unary   := '-' unary | primary
 * primary := NUMBER | '(' expr ')'
 * ```
 *
 * The input is a single line of ASCII bytes; spaces and tabs may separate tokens.
 * Instances are single-use and not thread-safe.
 */
class Evaluator private constructor(
    private val src: ByteArray,
    private var pos: Int,
    private val end: Int,
) {
    private fun expr(): Long {
        var value = term()
        while (true) {
            val op = peek()
            if (op != '+'.code && op != '-'.code) return value
            pos++
            value = apply(op.toChar(), value, term())
        }
    }

    private fun term(): Long {
        var value = unary()
        while (true) {
            val op = peek()
            if (op != '*'.code && op != '/'.code && op != '%'.code) return value
            pos++
            value = apply(op.toChar(), value, unary())
        }
    }

    private fun unary(): Long {
        // Iterate over runs of '-' rather than recursing, so long chains cannot exhaust the stack.
        var negations = 0
        while (peek() == '-'.code) {
            pos++
            negations++
        }
        var value = primary()
        repeat(negations) {
            if (value == Long.MIN_VALUE) fail("overflow")
            value = -value
        }
        return value
    }

    private fun primary(): Long {
        val c = peek()
        return when {
            c == '('.code -> {
                pos++
                val value = expr()
                if (peek() != ')'.code) fail("expected ')'")
                pos++
                value
            }
            isDigit(c) -> number()
            else -> fail("expected operand")
        }
    }

    private fun number(): Long {
        var value = 0L
        var overflow = false
        while (pos < end && isDigit(src[pos].toInt())) {
            val digit = src[pos++] - '0'.code.toByte()
            if (value > (Long.MAX_VALUE - digit) / 10) overflow = true else value = value * 10 + digit
        }
        if (overflow) fail("literal out of range")
        return value
    }

    /** Skips blanks and returns the next byte without consuming it, or -1 at end of input. */
    private fun peek(): Int {
        while (pos < end && isBlank(src[pos])) pos++
        return if (pos < end) src[pos].toInt() else -1
    }

    companion object {
        /** Evaluates `src[start, end)` as a complete expression. */
        @Throws(EvaluationException::class)
        fun evaluate(src: ByteArray, start: Int = 0, end: Int = src.size): Long {
            val evaluator = Evaluator(src, start, end)
            val value = evaluator.expr()
            if (evaluator.peek() != -1) fail("unexpected trailing input")
            return value
        }

        fun isBlank(c: Byte): Boolean = c == ' '.code.toByte() || c == '\t'.code.toByte()

        private fun isDigit(c: Int): Boolean = c in '0'.code..'9'.code

        private fun fail(message: String): Nothing = throw EvaluationException(message)

        private fun apply(op: Char, left: Long, right: Long): Long = try {
            when (op) {
                '+' -> Math.addExact(left, right)
                '-' -> Math.subtractExact(left, right)
                '*' -> Math.multiplyExact(left, right)
                '/' -> Math.divideExact(left, right.nonZero())
                '%' -> left % right.nonZero()
                else -> error("unknown operator $op")
            }
        } catch (e: ArithmeticException) {
            fail("overflow")
        }

        private fun Long.nonZero(): Long = also { if (it == 0L) fail("division by zero") }
    }
}

package calc

import java.io.InputStream
import java.io.OutputStream
import kotlin.system.exitProcess

/** Deeply nested parentheses recurse; run on a thread with a generous stack. */
private const val STACK_SIZE = 1L shl 30
private val ERROR = "error\n".toByteArray(Charsets.US_ASCII)

/** Reads one expression per line from standard input and prints its value or `error`. */
fun main() {
    var failure: Throwable? = null
    val worker = Thread(null, {
        try {
            run(System.`in`, System.out)
        } catch (t: Throwable) {
            failure = t
        }
    }, "calc", STACK_SIZE)
    worker.start()
    worker.join()
    failure?.let {
        it.printStackTrace()
        exitProcess(1)
    }
}

fun run(input: InputStream, output: OutputStream) {
    val out = output.buffered(1 shl 16)
    val reader = LineReader(input)
    while (reader.next()) {
        val line = reader.line
        val length = reader.length
        if ((0 until length).all { Evaluator.isBlank(line[it]) }) continue
        val result = try {
            "${Evaluator.evaluate(line, 0, length)}\n".toByteArray(Charsets.US_ASCII)
        } catch (_: EvaluationException) {
            ERROR
        } catch (_: StackOverflowError) {
            ERROR
        }
        out.write(result)
    }
    out.flush()
}

/** Minimal buffered reader that splits a byte stream on `'\n'`, reusing one line buffer. */
private class LineReader(private val input: InputStream) {
    private val buffer = ByteArray(1 shl 16)
    private var bufferPos = 0
    private var bufferLimit = 0

    /** Holds the current line in its first [length] bytes. */
    var line = ByteArray(256)
        private set
    var length = 0
        private set

    /** Advances to the next line; returns false at end of input. */
    fun next(): Boolean {
        length = 0
        var sawAny = false
        while (true) {
            if (bufferPos == bufferLimit) {
                bufferLimit = input.read(buffer).coerceAtLeast(0)
                bufferPos = 0
                if (bufferLimit == 0) return sawAny
            }
            sawAny = true
            val start = bufferPos
            while (bufferPos < bufferLimit && buffer[bufferPos] != NEWLINE) bufferPos++
            append(start, bufferPos)
            if (bufferPos < bufferLimit) {
                bufferPos++ // consume '\n'
                return true
            }
        }
    }

    private fun append(from: Int, to: Int) {
        val count = to - from
        if (length + count > line.size) {
            line = line.copyOf(maxOf(line.size * 2, length + count))
        }
        buffer.copyInto(line, length, from, to)
        length += count
    }

    private companion object {
        const val NEWLINE = '\n'.code.toByte()
    }
}
